import glob
import json
import os
import subprocess
import sys

START = 'public static int CompareVersions(string version1, string version2)'
END = 'return ver1.CompareTo(ver2);\n}'

DRIVER = r'''using System;
using System.Collections.Generic;
using System.IO;
using System.Text.Json;

public static class CandidateHost
{
@@FN@@
}

public static class Driver
{
    public static int Main(string[] args)
    {
        var results = new List<Dictionary<string, object>>();
        try
        {
            string json = File.ReadAllText("inputs.json");
            using JsonDocument doc = JsonDocument.Parse(json);
            foreach (JsonElement item in doc.RootElement.EnumerateArray())
            {
                var r = new Dictionary<string, object>();
                r["id"] = item.GetProperty("id").GetString();
                JsonElement inp = item.GetProperty("input");
                string a = inp.GetProperty("a").GetString();
                string b = inp.GetProperty("b").GetString();
                TextWriter saved = Console.Out;
                try
                {
                    Console.SetOut(new StringWriter());
                    int v = CandidateHost.CompareVersions(a, b);
                    r["actual"] = v;
                }
                catch (Exception ex)
                {
                    r["error"] = ex.GetType().Name + ": " + ex.Message;
                }
                finally
                {
                    Console.SetOut(saved);
                }
                results.Add(r);
            }
            var outObj = new Dictionary<string, object> { { "results", results } };
            Console.WriteLine(JsonSerializer.Serialize(outObj));
        }
        catch (Exception ex)
        {
            var outObj = new Dictionary<string, object> { { "results", results }, { "harness_error", ex.GetType().Name + ": " + ex.Message } };
            Console.WriteLine(JsonSerializer.Serialize(outObj));
        }
        return 0;
    }
}
'''


def emit(obj):
    sys.stdout.write(json.dumps(obj) + '\n')


def fail(msg, detail=''):
    if detail:
        msg = msg + ': ' + detail[-400:]
    emit({'results': [], 'harness_error': msg})
    sys.exit(0)


def main():
    here = os.getcwd()
    try:
        with open(os.path.join(here, 'block-0.txt'), encoding='utf-8') as fh:
            src = fh.read()
    except OSError as exc:
        fail('cannot read block-0.txt: ' + str(exc))
    s = src.find(START)
    e = src.find(END)
    if s < 0 or e < s:
        fail('candidate anchors not found in block-0.txt')
    fn = src[s:e + len(END)]
    with open(os.path.join(here, 'Driver.cs'), 'w', encoding='utf-8') as fh:
        fh.write(DRIVER.replace('@@FN@@', fn))

    dotnet_root = os.environ.get('DOTNET_ROOT')
    if not dotnet_root:
        fail('DOTNET_ROOT is not set')
    csc = sorted(glob.glob(os.path.join(dotnet_root, 'sdk', '*', 'Roslyn', 'bincore', 'csc.dll')))
    if not csc:
        fail('Roslyn csc.dll not found under DOTNET_ROOT')
    packs = sorted(glob.glob(os.path.join(dotnet_root, 'packs', 'Microsoft.NETCore.App.Ref', '*')))
    if not packs:
        fail('Microsoft.NETCore.App.Ref pack not found')
    dlls = sorted(glob.glob(os.path.join(packs[-1], 'ref', 'net8.0', '*.dll')))
    if not dlls:
        fail('net8.0 reference assemblies not found')
    with open(os.path.join(here, 'refs.rsp'), 'w', encoding='utf-8') as fh:
        for d in dlls:
            fh.write('-r:' + d + '\n')
    with open(os.path.join(here, 'Candidate.runtimeconfig.json'), 'w', encoding='utf-8') as fh:
        json.dump({'runtimeOptions': {'tfm': 'net8.0', 'framework': {'name': 'Microsoft.NETCore.App', 'version': '8.0.0'}}}, fh)

    try:
        comp = subprocess.run(['dotnet', csc[-1], '-nologo', '-target:exe', '-out:Candidate.dll', '@refs.rsp', 'Driver.cs'], capture_output=True, text=True, timeout=5, cwd=here)
    except subprocess.TimeoutExpired:
        fail('compile timed out')
    if comp.returncode != 0:
        fail('compile failed', comp.stdout + comp.stderr)

    try:
        run = subprocess.run(['dotnet', 'Candidate.dll'], capture_output=True, text=True, timeout=5, cwd=here)
    except subprocess.TimeoutExpired:
        fail('driver timed out')
    lines = [ln for ln in run.stdout.splitlines() if ln.strip()]
    if not lines:
        fail('driver produced no output', run.stderr)
    try:
        obj = json.loads(lines[-1])
    except ValueError:
        fail('driver output was not JSON', run.stdout)
    emit(obj)


if __name__ == '__main__':
    main()

import glob, json, os, subprocess, sys

ENV = dict(os.environ)
ENV.update({"DOTNET_CLI_TELEMETRY_OPTOUT": "1", "DOTNET_NOLOGO": "1", "DOTNET_SKIP_FIRST_TIME_EXPERIENCE": "1", "DOTNET_CLI_HOME": os.getcwd()})

def fail(msg):
    sys.stdout.write(json.dumps({"results": [], "harness_error": msg}) + "\n")
    sys.exit(0)

def run(args):
    try:
        return subprocess.run(args, cwd=os.getcwd(), env=ENV, capture_output=True, text=True, timeout=5)
    except subprocess.TimeoutExpired:
        fail("timeout (5s) running: " + " ".join(os.path.basename(a) for a in args))
    except OSError as e:
        fail("cannot start process: %s" % e)

def main():
    try:
        with open("inputs.json", encoding="utf-8") as f:
            json.load(f)
    except Exception as e:
        fail("cannot read inputs.json: %s" % e)
    try:
        with open("block-0.txt", encoding="utf-8") as f:
            cand = f.read()
    except Exception as e:
        fail("cannot read block-0.txt: %s" % e)
    root = os.environ.get("DOTNET_ROOT") or "/usr/local/share/dotnet"
    csc = sorted(glob.glob(os.path.join(root, "sdk", "*", "Roslyn", "bincore", "csc.dll")))
    refdirs = sorted(glob.glob(os.path.join(root, "packs", "Microsoft.NETCore.App.Ref", "*", "ref", "net8.0")))
    if not csc or not refdirs:
        fail("Roslyn csc.dll or net8.0 reference pack not found under " + root)
    refs = sorted(glob.glob(os.path.join(refdirs[-1], "*.dll")))
    dotnet = os.path.join(root, "dotnet")
    if not os.path.exists(dotnet):
        dotnet = "dotnet"
    with open("Candidate.cs", "w", encoding="utf-8") as f:
        f.write(cand)
    with open("refs.rsp", "w", encoding="utf-8") as f:
        for r in refs:
            f.write('-r:"' + r + '"\n')
    with open("Candidate.runtimeconfig.json", "w", encoding="utf-8") as f:
        json.dump({"runtimeOptions": {"tfm": "net8.0", "framework": {"name": "Microsoft.NETCore.App", "version": "8.0.0"}}}, f)
    c = run([dotnet, csc[-1], "-nologo", "-target:exe", "-out:Candidate.dll", "@refs.rsp", "Candidate.cs", "Main.cs"])
    if c.returncode != 0:
        fail("compile failed: " + (c.stdout + c.stderr)[-3000:])
    r = run([dotnet, "Candidate.dll"])
    if r.returncode != 0 or not r.stdout.strip():
        fail("run failed (exit %s): %s" % (r.returncode, (r.stderr or r.stdout)[-2000:]))
    try:
        obj = json.loads(r.stdout.strip().splitlines()[-1])
    except Exception:
        fail("unparseable harness output: " + r.stdout[-1000:])
    sys.stdout.write(json.dumps(obj) + "\n")

main()

